{
  "name": "@workspace/core",
  "version": "0.52.1",
  "description": "Platform-neutral Application product contracts and state primitives.",
  "private": true,
  "type": "module",
  "exports": {
    "./*": {
      "types": "./src/*.ts",
      "default": "./src/*.ts"
    }
  },
  "scripts": {
    "build": "tsc --noEmit",
    "typecheck": "node ../scripts/typecheck.mjs plain --noEmit",
    "lint": "node ../scripts/typecheck.mjs plain --noEmit",
    "test": "vitest run",
    "test:coverage": "vitest run --coverage",
    "test:watch": "vitest watch"
  },
  "devDependencies": {
    "@codex-app-sdk/core": "0.21.3",
    "@types/node": "^25.9.1",
    "@vitest/coverage-v8": "4.1.8",
    "typescript": "^6.0.3",
    "vitest": "^4.1.8"
  },
  "dependencies": {
    "@noble/hashes": "^2.0.1",
    "chart.js": "4.6.1",
    "rrule-temporal": "2.2.8"
  }
}

{
  "name": "@workspace/cli",
  "version": "0.1.1",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "node build.mjs",
    "dev": "node build.mjs --quiet && node dist/cli.mjs",
    "typecheck": "node ../../scripts/typecheck.mjs plain --noEmit",
    "lint": "node ../../scripts/typecheck.mjs plain --noEmit",
    "test": "vitest run",
    "test:coverage": "vitest run --coverage",
    "test:watch": "vitest watch",
    "test:package": "node --test build.test.mjs package-workflows.test.mjs"
  },
  "dependencies": {
    "@workspace/core": "0.52.1"
  },
  "devDependencies": {
    "@types/node": "^25.9.1",
    "@vitest/coverage-v8": "4.1.8",
    "esbuild": "0.28.2",
    "typescript": "^6.0.3",
    "vitest": "4.1.8"
  },
  "engines": {
    "node": ">=22"
  }
}

{
  "name": "korus-films",
  "private": true,
  "type": "module",
  "scripts": {
    "prepare:assets": "node assets.mjs",
    "studio": "npm run prepare:assets && remotion studio src/index.tsx",
    "render": "node render.mjs",
    "typecheck": "npm run prepare:assets && tsc --noEmit",
    "test": "node --test ../film-timing.test.mjs ../narration.test.mjs"
  },
  "dependencies": {
    "@remotion/cli": "4.0.534",
    "@remotion/bundler": "4.0.534",
    "@remotion/renderer": "4.0.534",
    "react": "19.3.0",
    "react-dom": "19.3.0",
    "remotion": "4.0.534"
  },
  "devDependencies": {
    "@types/react": "^19.2.0",
    "@types/react-dom": "^19.2.0",
    "jsdom": "29.0.1",
    "typescript": "^6.0.3"
  }
}
